// Authoritative Server Route enforcing AuthN + AuthZ cleanly
export async function DELETE(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { userId } = await auth();
  if (!userId) return Response.json({ error: "Unauthorized" }, { status: 401 });

  const { id } = await params;
  // Ownership check enforced directly inside the DELETE predicate
  const deleted = await db.from("projects").delete().eq("id", id).eq("owner_clerk_user_id", userId);
  if (!deleted.count) return Response.json({ error: "Forbidden or not found" }, { status: 404 });

  return Response.json({ success: true });
}

